CREATE TABLE CPF_BATCH_EXECUTION_CONTROL_R89_BAK AS SELECT * FROM CPF_BATCH_EXECUTION_CONTROL;
CREATE TABLE CPF_BATCH_EXECUTION_EPOCH_R89_BAK AS SELECT * FROM CPF_BATCH_EXECUTION_EPOCH;
DECLARE v_count NUMBER; BEGIN
  SELECT COUNT(*) INTO v_count FROM (SELECT idempotency_key FROM CPF_BATCH_EXECUTION_CONTROL GROUP BY idempotency_key HAVING COUNT(*) > 1);
  IF v_count > 0 THEN RAISE_APPLICATION_ERROR(-20189, 'R89 cannot restore global idempotency uniqueness; checkpoint retained'); END IF;
END;
/
DROP TABLE CPF_BATCH_EXECUTION_EPOCH;
DROP INDEX IX_CPF_BAT_EXEC_RECONCILE;
DROP INDEX UK_CPF_BAT_EXEC_IDEM_SCOPE;
ALTER TABLE CPF_BATCH_EXECUTION_CONTROL DROP CONSTRAINT CK_CPF_BAT_REQUEST_HASH;
ALTER TABLE CPF_BATCH_EXECUTION_CONTROL DROP CONSTRAINT CK_CPF_BAT_PLAN_HASH;
ALTER TABLE CPF_BATCH_EXECUTION_CONTROL DROP CONSTRAINT CK_CPF_BAT_CONTROL_VERSION;
ALTER TABLE CPF_BATCH_EXECUTION_CONTROL DROP CONSTRAINT CK_CPF_BAT_RECONCILE_ATTEMPT;
ALTER TABLE CPF_BATCH_EXECUTION_CONTROL DROP (
  idempotency_scope, request_hash, plan_checksum, control_version, reconcile_attempts,
  reconcile_after, last_error_code, last_error_detail
);
ALTER TABLE CPF_BATCH_EXECUTION_CONTROL ADD CONSTRAINT UK_CPF_BAT_EXEC_IDEM_LEGACY UNIQUE(idempotency_key);
